#include <bits/stdc++.h>
using namespace std;

class Car
{

public:
    int mileage;
    int sittingCapacity;
    char *name;
    Car()
    {
        this->name = new char[100];
        cout << "Default constructor got called" << endl;
    }
    Car(char *name, int mileage, int sittingCapacity)
    {
        this->name = name;
        this->mileage = mileage;
        this->sittingCapacity = sittingCapacity;
    }
    // This is known as copy constructor. This is used when you have to copy one object data to another
    // this is also auto generated by compiler. And below is the way how you can define custom copy constructor.
    // here & is mandatory because if you dont write it, object will be passed as "pass by value" method and it will create continuous loop
    // because when pass by value triggers, that method also under the hood uses copy constructor and copy constructor will get call itself.
    // default copy constructor create shallow copy instead of deep copy
    Car(Car &carToCopy)
    {
        // this is how shallow copy works
        // this->name = carToCopy.name;
        // for deep copy we need to create new heap memory pointer and copy data in that manually
        char *name = new char[100];
        strcpy(name, carToCopy.name);
        this->name = name;
        this->mileage = carToCopy.mileage;
        this->sittingCapacity = carToCopy.sittingCapacity;
    }
    void print()
    {
        cout << "[name: " << this->name << ", mileage: " << this->mileage << ", sittingCapacity: " << this->sittingCapacity << "]" << endl;
    }
};
int main()
{
    char *name = new char[100];
    strcpy(name, "nexon");
    Car nexon(name, 25, 5);
    nexon.print();

    Car punch(nexon);
    punch.print();
    // if shallow copy done same pointer has been shared between both objects so below modification will modify original data instead of modifying punch
    punch.name[0] = 'P';
    nexon.print();
    punch.print();
}